    public function index()
    {
        $user = Auth::user();
        return view('tools.contrat-pret', [
            'currencies'      => $this->currencies,
            'translations'    => $this->translations,
            'freeUsed'        => $user ? (bool) $user->contrat_free_used : false,
        ]);
    }

    public function generate(Request $request)
    {
        $request->validate([
            'emprunteur_nom'   => 'required|string|max:100',
            'emprunteur_pays'  => 'required|string|max:60',
            'emprunteur_id'    => 'nullable|string|max:50',
            'preteur_nom'      => 'required|string|max:100',
            'preteur_pays'     => 'required|string|max:60',
            'preteur_adresse'  => 'required|string|max:200',
            'preteur_id'       => 'required|string|max:50',
            'preteur_capacite' => 'required|string|max:80',
            'montant'          => 'required|numeric|min:1',
            'devise'           => 'required|string|in:' . implode(',', array_keys($this->currencies)),
            'taux'             => 'required|numeric|min:0|max:100',
            'duree'            => 'required|integer|min:1|max:360',
            'lang'             => 'required|string|in:fr,en,es,pt,de,it,nl,pl,hr,ru',
        ]);

        // Génération gratuite (1ère fois) ou payante (crédits requis)
        $user = Auth::user();
        $cost = 1250;
        $isTestGeneration = false;

        if (!$user->contrat_free_used) {
            // Première génération : gratuite avec filigrane
            $isTestGeneration = true;
        } elseif ($user->credit_user < $cost) {
            return back()->withErrors([
                'credits' => 'Crédits insuffisants. Il vous faut au moins ' . number_format($cost, 0, ',', ' ') . ' crédits pour générer un contrat de prêt. Votre solde actuel : ' . number_format($user->credit_user, 0, ',', ' ') . ' crédits.',
            ])->withInput();
        }

        $lang          = $request->lang;
        $devise        = $request->devise;
        $t             = $this->translations[$lang] ?? $this->translations['fr'];
        $deviseSymbole = $this->currencies[$devise]['symbol'] ?? '€';
        $contractNo    = $request->filled('contract_no')
                       ? strtoupper(trim($request->contract_no))
                       : strtoupper(substr($request->emprunteur_nom, 0, 3)) . '-' . date('Y') . '-' . rand(1000, 9999);

        $signatureEmprunteur = null;

        // Priorité : données traitées (fond blanc supprimé côté client) — sinon fichier brut
        $signaturePreteur = null;
        $preteurData = $request->input('signature_preteur_data', '');
        if (!empty($preteurData) && str_starts_with($preteurData, 'data:image/')) {
            $signaturePreteur = $preteurData;
        } elseif ($request->hasFile('signature_preteur') && $request->file('signature_preteur')->isValid()) {
            $signaturePreteur = 'data:' . $request->file('signature_preteur')->getMimeType() . ';base64,'
                              . base64_encode(file_get_contents($request->file('signature_preteur')->getRealPath()));
        }

        $pdf = Pdf::loadView('tools.contrat-pret-pdf', [
            'lang'                => $lang,
            't'                   => $t,
            'contractNo'          => $contractNo,
            'emprunteurNom'       => $request->emprunteur_nom,
            'emprunteurPays'      => $request->emprunteur_pays,
            'emprunteurId'        => $request->emprunteur_id,
            'preteurNom'          => $request->preteur_nom,
            'preteurPays'         => $request->preteur_pays,
            'preteurAdresse'      => $request->preteur_adresse,
            'preteurId'           => $request->preteur_id,
            'preteurCapacite'     => $request->preteur_capacite,
            'montant'             => (float) $request->montant,
            'devise'              => $devise,
            'deviseSymbole'       => $deviseSymbole,
            'taux'                => (float) $request->taux,
            'duree'               => (int) $request->duree,
            'signatureEmprunteur' => $signatureEmprunteur,
            'signaturePreteur'    => $signaturePreteur,
            'customArticles'      => $request->input('articles', []),
            'isTestGeneration'    => $isTestGeneration,
        ])->setPaper('a4', 'portrait');

        $filename = 'contrat-pret-'
            . strtolower(str_replace(' ', '-', $request->emprunteur_nom))
            . '-' . date('Ymd') . '.pdf';

        // Après génération réussie : marquer la gratuite ou déduire les crédits
        if ($isTestGeneration) {
            DB::table('users')->where('id', $user->id)->update(['contrat_free_used' => true]);
        } else {
            DB::table('users')->where('id', $user->id)->decrement('credit_user', $cost);
        }

        return $pdf->download($filename);
    }
}
